  values ('bridgepointgroup.com/about-us/news-and-insights/press-releases/2026/bridgepoint-credit-announces-eur1bn-continuation-vehicle-led-by-pantheon', '2026-09-08', 'private_credit', 'deal', 'Bridgepoint Credit moves €1.2bn of Direct Lending II loans into a Pantheon-led continuation vehicle', 'Senior secured loans to European middle-market companies from the 2017-vintage fund; investors could cash out or roll; oversubscribed after a competitive process.', array['Bridgepoint', 'Pantheon']::text[], (select coalesce(array_agg(id), '{}'::uuid[]) from public.companies where lower(name) = any(array['bridgepoint', 'pantheon']::text[])), 'Bridgepoint', 'https://www.bridgepointgroup.com/about-us/news-and-insights/press-releases/2026/bridgepoint-credit-announces-eur1bn-continuation-vehicle-led-by-pantheon', 'web_research')
